class BaseR5222:
    def base_value(self):
        return 1


class HelperR5222:
    def apply(self, value):
        return value * 2


class AccountR5222(BaseR5222):
    def __init__(self):
        self.amount = 760
        self.helper = HelperR5222()

    def calculate(self, value, tax, discount):
        subtotal = value + tax
        adjusted = subtotal - discount
        total = adjusted + self.base_value()
        return total

    def process(self, value, tax, discount, fee):
        return value + tax - discount + fee

    def delegated(self, value):
        return self.helper.apply(value)

    def category_fee(self, kind):
        if kind == "premium":
            return self.amount * 2
        return self.amount

    def nested(self, value):
        if value > 0:
            if value < 100:
                return value
        return 0

    def parse(self, text):
        try:
            return int(text)
        except:
            return 0

    def unused_R5222(self):
        return -1


class ChildR5222(BaseR5222):
    def shared_R5222(self, value):
        return value + self.base_value()

